<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { IonBackButton, IonButtons, IonContent, IonHeader, IonPage, IonTitle, IonToolbar } from '@ionic/vue'
import { formatMoney } from '../../components/MoneyAmount.vue'
import { isStrictId } from '../../data/identifiers'
import type { CurrencyCode } from '../../domain/money'
import type { GroupPremiumSnapshot } from '../premium/premiumData'
import { loadGroupPremiumSnapshot } from '../premium/premiumData'

const route = useRoute(); const snapshot = ref<GroupPremiumSnapshot>(); const error = ref(''); const loading = ref(false); let request = 0
const groupId = computed(() => typeof route.params.groupId === 'string' && isStrictId(route.params.groupId) ? route.params.groupId : '')
const backPath = computed(() => groupId.value ? `/tabs/groups/${encodeURIComponent(groupId.value)}` : '/tabs/groups')
const currencies = computed(() => [...new Set(snapshot.value?.report.totals.map(({ currency }) => currency) ?? [])])
watch(groupId, (id) => { void load(id) }, { immediate: true })
async function load(id: string): Promise<void> { const current = ++request; loading.value = true; error.value = ''; snapshot.value = undefined; try { const loaded = await loadGroupPremiumSnapshot(id); if (current === request) snapshot.value = loaded } catch (reason) { if (current === request) error.value = reason instanceof Error ? reason.message : String(reason) } finally { if (current === request) loading.value = false } }
function categories(currency: CurrencyCode) { return snapshot.value?.report.category.filter((row) => row.currency === currency) ?? [] }
function days(currency: CurrencyCode) { return snapshot.value?.report.daily.filter((row) => row.currency === currency) ?? [] }
function months(currency: CurrencyCode) { return snapshot.value?.report.monthly.filter((row) => row.currency === currency) ?? [] }
function contributions(currency: CurrencyCode) { return snapshot.value?.report.memberContributions.filter((row) => row.currency === currency) ?? [] }
function balancePoints(currency: CurrencyCode) { return snapshot.value?.report.balanceOverTime.filter((row) => row.currency === currency) ?? [] }
function maxCategory(currency: CurrencyCode): number { return Math.max(1, ...categories(currency).map(({ minorAmount }) => minorAmount)) }
function maxDay(currency: CurrencyCode): number { return maximum(days(currency).map(({ minorAmount }) => minorAmount)) }
function maxMonth(currency: CurrencyCode): number { return maximum(months(currency).map(({ minorAmount }) => minorAmount)) }
function maxContribution(currency: CurrencyCode): number { return maximum(contributions(currency).flatMap(({ paidMinor, shareMinor }) => [paidMinor, shareMinor])) }
function maxBalance(currency: CurrencyCode): number { return maximum(balancePoints(currency).map(({ minorAmount }) => Math.abs(minorAmount))) }
function barStyle(value: number, maximumValue: number, half = false): Record<string, string> { return { '--plot-width': `${Math.min(half ? 50 : 100, Math.abs(value) / Math.max(1, maximumValue) * (half ? 50 : 100))}%` } }
function maximum(values: readonly number[]): number { return Math.max(1, ...values) }
function money(currency: CurrencyCode, minorAmount: number): string { return formatMoney({ currency, minorAmount }) }
function signedMoney(currency: CurrencyCode, minorAmount: number): string { return `${minorAmount > 0 ? '+' : minorAmount < 0 ? '−' : ''}${money(currency, Math.abs(minorAmount))}` }
function memberName(participantId: string): string { return snapshot.value?.members.find(({ id }) => id === participantId)?.displayName ?? 'Unknown member' }
function dayLabel(date: string): string { return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', timeZone: 'UTC' }).format(new Date(`${date}T00:00:00.000Z`)) }
function coverage(): string { return snapshot.value?.report.coverage.status === 'complete' ? 'Complete demo history · confirmed current records only' : 'Bounded authorized snapshot · complete historical charts require the server provider' }
</script>

<template>
  <ion-page><ion-header translucent><ion-toolbar><ion-buttons slot="start"><ion-back-button :default-href="backPath" text="Group" /></ion-buttons><ion-title>Charts</ion-title></ion-toolbar></ion-header>
    <ion-content :fullscreen="true"><main class="charts-main"><p class="eyebrow">{{ snapshot?.group.name ?? 'Group report' }}</p><h1>Charts</h1><p class="intro">Every plotted value is also available in an exact table.</p>
      <p v-if="loading" role="status">Loading confirmed charts…</p><p v-else-if="error" role="alert" class="error">{{ error }}</p>
      <template v-else-if="snapshot"><p data-testid="coverage" class="coverage">{{ coverage() }}</p>
        <section v-for="currency in currencies" :key="currency" class="currency-report" :aria-labelledby="`currency-${currency}`"><h2 :id="`currency-${currency}`">{{ currency }}</h2><p :data-testid="`chart-scale-${currency}`" class="currency-legend"><span><i class="legend-swatch legend-swatch--paid" /> Spending or paid</span><span><i class="legend-swatch legend-swatch--share" /> Share</span><span>All scales are independent within {{ currency }}.</span></p>
          <section class="chart-card"><h3>Spending by category</h3><ul class="meter-list" aria-hidden="true"><li v-for="row in categories(currency)" :key="row.category"><span>{{ row.category }}</span><meter min="0" :max="maxCategory(currency)" :value="row.minorAmount" /><strong>{{ money(currency, row.minorAmount) }}</strong></li></ul>
            <table :aria-label="`${currency} spending by category`"><thead><tr><th scope="col">Category</th><th scope="col">Amount</th></tr></thead><tbody><tr v-for="row in categories(currency)" :key="row.category"><th scope="row">{{ row.category }}</th><td>{{ money(currency, row.minorAmount) }}</td></tr></tbody></table></section>
          <section class="chart-card"><h3>Daily spending</h3><p class="plot-scale">Scale: {{ money(currency, 0) }}–{{ money(currency, maxDay(currency)) }}</p><ul :data-testid="`daily-plot-${currency}`" class="bar-plot" aria-hidden="true"><li v-for="row in days(currency)" :key="row.date"><span>{{ dayLabel(row.date) }}</span><span class="bar-track"><i class="bar-fill" :style="barStyle(row.minorAmount, maxDay(currency))" /></span><strong>{{ money(currency, row.minorAmount) }}</strong></li></ul><table :aria-label="`${currency} daily spending`"><thead><tr><th scope="col">Date</th><th scope="col">Amount</th></tr></thead><tbody><tr v-for="row in days(currency)" :key="row.date"><th scope="row">{{ dayLabel(row.date) }}</th><td>{{ money(currency, row.minorAmount) }}</td></tr></tbody></table></section>
          <section class="chart-card"><h3>Monthly spending</h3><p class="plot-scale">Scale: {{ money(currency, 0) }}–{{ money(currency, maxMonth(currency)) }}</p><ul :data-testid="`monthly-plot-${currency}`" class="bar-plot" aria-hidden="true"><li v-for="row in months(currency)" :key="row.month"><span>{{ row.month }}</span><span class="bar-track"><i class="bar-fill" :style="barStyle(row.minorAmount, maxMonth(currency))" /></span><strong>{{ money(currency, row.minorAmount) }}</strong></li></ul><table :aria-label="`${currency} monthly spending`"><thead><tr><th scope="col">Month</th><th scope="col">Amount</th></tr></thead><tbody><tr v-for="row in months(currency)" :key="row.month"><th scope="row">{{ row.month }}</th><td>{{ money(currency, row.minorAmount) }}</td></tr></tbody></table></section>
          <section class="chart-card"><h3>Member contributions</h3><p class="plot-scale">Scale: {{ money(currency, 0) }}–{{ money(currency, maxContribution(currency)) }}</p><ul :data-testid="`contribution-plot-${currency}`" class="contribution-plot" aria-hidden="true"><li v-for="row in contributions(currency)" :key="row.participantId"><span>{{ memberName(row.participantId) }}</span><span class="paired-bars"><i class="bar-track"><b class="bar-fill" :style="barStyle(row.paidMinor, maxContribution(currency))" /></i><i class="bar-track"><b class="bar-fill bar-fill--share" :style="barStyle(row.shareMinor, maxContribution(currency))" /></i></span></li></ul><table :aria-label="`${currency} member contributions`"><thead><tr><th scope="col">Member</th><th scope="col">Paid</th><th scope="col">Share</th></tr></thead><tbody><tr v-for="row in contributions(currency)" :key="row.participantId"><th scope="row">{{ memberName(row.participantId) }}</th><td>{{ money(currency, row.paidMinor) }}</td><td>{{ money(currency, row.shareMinor) }}</td></tr></tbody></table></section>
          <section class="chart-card"><h3>Your ledger position over time</h3><p class="chart-note">Positive means you were owed; negative means you owed. Saved non-void payments are included.</p><p class="plot-scale">Scale: −{{ money(currency, maxBalance(currency)) }} to +{{ money(currency, maxBalance(currency)) }}</p><ul :data-testid="`balance-plot-${currency}`" class="balance-plot" aria-hidden="true"><li v-for="row in balancePoints(currency)" :key="row.id"><span>{{ dayLabel(row.occurredOn) }}</span><span class="balance-track"><i class="balance-axis" /><b class="balance-fill" :class="row.minorAmount < 0 ? 'balance-fill--negative' : 'balance-fill--positive'" :style="barStyle(row.minorAmount, maxBalance(currency), true)" /></span><strong>{{ signedMoney(currency, row.minorAmount) }}</strong></li></ul><table :aria-label="`${currency} balance over time`"><thead><tr><th scope="col">Date</th><th scope="col">Ledger position</th></tr></thead><tbody><tr v-for="row in balancePoints(currency)" :key="row.id"><th scope="row">{{ dayLabel(row.occurredOn) }}</th><td>{{ signedMoney(currency, row.minorAmount) }}</td></tr></tbody></table></section>
        </section><p v-if="!currencies.length" class="empty">No confirmed expenses to chart yet.</p>
      </template>
    </main></ion-content></ion-page>
</template>

<style scoped>
.charts-main { width: min(100%, 720px); margin: 0 auto; padding: 22px 18px calc(42px + env(safe-area-inset-bottom)); }.eyebrow { margin: 0 0 4px; color: var(--su-accent); font-size: .78rem; font-weight: 700; text-transform: uppercase; }.charts-main h1 { margin: 0; font-size: clamp(2rem, 9vw, 2.55rem); letter-spacing: -.045em; }.intro { margin: 8px 0 20px; color: var(--ion-color-medium); }.coverage { padding: 11px 13px; border-radius: 13px; background: var(--su-lilac); color: var(--su-category-fg); font-size: .84rem; }.currency-report > h2 { margin: 24px 0 8px; font-size: 1rem; letter-spacing: .08em; }.currency-legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 0 0 10px; color: var(--ion-color-medium); font-size: .75rem; }.currency-legend > span { display: inline-flex; align-items: center; gap: 5px; }.legend-swatch { width: 9px; height: 9px; border-radius: 3px; background: var(--su-accent); }.legend-swatch--share { background: var(--su-indigo); }.chart-card { margin: 12px 0; padding: 16px; border: 1px solid color-mix(in srgb, var(--su-divider) 34%, transparent); border-radius: 18px; }.chart-card h3 { margin: 0 0 12px; font-size: 1rem; }.chart-note, .plot-scale { color: var(--ion-color-medium); font-size: .78rem; line-height: 1.4; }.chart-note { margin: -5px 0 8px; }.plot-scale { margin: -5px 0 10px; }.meter-list, .bar-plot, .contribution-plot, .balance-plot { display: grid; gap: 10px; margin: 0 0 14px; padding: 0; list-style: none; }.meter-list li, .bar-plot li, .balance-plot li { display: grid; grid-template-columns: minmax(72px, .8fr) minmax(80px, 1.4fr) auto; align-items: center; gap: 8px; font-size: .82rem; }.meter-list meter { width: 100%; height: 12px; accent-color: var(--su-accent); }.meter-list strong, .bar-plot strong, .balance-plot strong { font-variant-numeric: tabular-nums; }.bar-track, .paired-bars .bar-track { position: relative; display: block; height: 8px; overflow: hidden; border-radius: 4px; background: color-mix(in srgb, var(--su-divider) 30%, transparent); }.bar-fill { display: block; width: var(--plot-width); height: 100%; border-radius: inherit; background: var(--su-accent); transform-origin: left center; animation: chart-reveal var(--su-motion-route) cubic-bezier(.2,.8,.2,1) both; }.bar-fill--share { background: var(--su-indigo); }.contribution-plot li { display: grid; grid-template-columns: minmax(88px, .8fr) minmax(120px, 1.7fr); align-items: center; gap: 8px; font-size: .82rem; }.paired-bars { display: grid; gap: 4px; }.balance-track { position: relative; display: block; height: 10px; border-radius: 5px; background: color-mix(in srgb, var(--su-divider) 24%, transparent); }.balance-axis { position: absolute; inset: -2px auto -2px 50%; width: 1px; background: var(--ion-color-medium); opacity: .55; }.balance-fill { position: absolute; top: 1px; width: var(--plot-width); height: 8px; border-radius: 4px; animation: chart-reveal var(--su-motion-route) cubic-bezier(.2,.8,.2,1) both; }.balance-fill--positive { left: 50%; background: var(--su-owed); transform-origin: left center; }.balance-fill--negative { right: 50%; background: var(--su-owing); transform-origin: right center; }table { width: 100%; border-collapse: collapse; }th, td { padding: 10px 4px; border-top: 1px solid color-mix(in srgb, var(--su-divider) 28%, transparent); font-size: .86rem; }th { text-align: left; }td { font-variant-numeric: tabular-nums; text-align: right; }.error { color: var(--su-owing); }.empty { color: var(--ion-color-medium); text-align: center; }
@keyframes chart-reveal { from { opacity: .4; transform: scaleX(0); } to { opacity: 1; transform: scaleX(1); } }
@media (max-width: 390px) { .chart-card { margin-inline: -2px; padding: 14px; }.meter-list li, .bar-plot li, .balance-plot li { grid-template-columns: 68px minmax(64px, 1fr) auto; }.meter-list strong, .bar-plot strong, .balance-plot strong { font-size: .74rem; } }
</style>
